184→// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
185→// and the raw transcript (full.jsonl) from /full/* refs (current + archived generations).
186→// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
187→// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
188→// Returns ErrNoTranscript if the session exists but no raw transcript is available.
189→// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
190→func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
191→	if err := ctx.Err(); err != nil {
192→		return nil, err //nolint:wrapcheck // Propagating context cancellation
193→	}
194→
195→	refName := plumbing.ReferenceName(paths.V2MainRefName)
196→	_, rootTreeHash, err := s.GetRefState(refName)
197→	if err != nil {
198→		return nil, ErrCheckpointNotFound
199→	}
200→
201→	rootTree, err := s.repo.TreeObject(rootTreeHash)
202→	if err != nil {
203→		return nil, ErrCheckpointNotFound
204→	}
205→
206→	cpTree, err := rootTree.Tree(checkpointID.Path())
207→	if err != nil {
208→		return nil, ErrCheckpointNotFound
209→	}
210→
211→	sessionDir := strconv.Itoa(sessionIndex)
212→	sessionTree, err := cpTree.Tree(sessionDir)
213→	if err != nil {
214→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
215→	}
