	var found bool
	for _, p := range points {
		if p.CheckpointID == cpID {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected to find checkpoint %s from merged feature branch on default branch, got %d points: %v", cpID, len(points), points)
	}
}

