	}
	if _, err := w.Add(".entire"); err != nil {
		t.Fatalf("failed to add .entire: %v", err)
	}
	commitHash, err := w.Commit("metadata only commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@example.com", When: time.Now()},
