	// First line should be prompt 2 (u2), not prompt 1
	if lines[0].UUID != "u2" {
		t.Errorf("expected first line to be u2 (prompt 2), got %s", lines[0].UUID)
	}

	// Last line should be prompt 3 (u3)
	if lines[2].UUID != "u3" {
